Deque<Integer> stack = new ArrayDeque<>();
stack.push(1);
stack.push(2);
stack.push(3);
stack.pop();
System.out.println(stack.peek());

int[] a = {1, 3, 5, 7, 9, 11, 13};
int low = 0;
int high = a.length - 1;
int steps = 0;
while (low <= high) {
    int mid = (low + high) / 2;
    steps++;
    if (a[mid] == 11) {
        break;
    }
    if (a[mid] < 11) {
        low = mid + 1;
    } else {
        high = mid - 1;
    }
}
System.out.println(steps);

int[] a = {3, 1, 2};
int swaps = 0;
for (int i = 0; i < a.length - 1; i++) {
    for (int j = 0; j < a.length - 1 - i; j++) {
        if (a[j] > a[j + 1]) {
            int tmp = a[j];
            a[j] = a[j + 1];
            a[j + 1] = tmp;
            swaps++;
        }
    }
}
System.out.println(swaps);
